#!/bin/sh
# Claude Code PreToolUse hook (Read|Edit|Write|MultiEdit): protect generated files and secret files.
# The tool call arrives as JSON on stdin; exit 2 blocks it and shows stderr to Claude.
input=$(cat)

tool=$(printf '%s' "$input" | sed -n 's/.*"tool_name" *: *"\([^"]*\)".*/\1/p' | head -n 1)
path=$(printf '%s' "$input" | sed -n 's/.*"file_path" *: *"\([^"]*\)".*/\1/p' | head -n 1)
[ -n "$path" ] || exit 0

# JSON escapes Windows separators; compare on the file name only.
name=${path##*[\\/]}

case "$name" in
  appsettings.Production*.json|.env|.env.*|secrets.json)
    echo "Blocked: $name holds secrets. Ask the user instead of reading or editing it." >&2
    exit 2
    ;;
esac

[ "$tool" = "Read" ] && exit 0

case "$name" in
  *ModelSnapshot.cs|*.Designer.cs)
    echo "Blocked: $name is generated by EF Core. Change the entity or configuration and run 'dotnet ef migrations add' (or 'migrations remove' for a migration never applied)." >&2
    exit 2
    ;;
esac
exit 0
